def extended_gcd(a, b):
    quotients = []
    r0, r1 = a, b
    while r1 != 0:
        q = r0 // r1
        quotients.append(q)
        r0, r1 = r1, r0 - q * r1
    g = r0
    x, y = 1, 0
    for q in reversed(quotients):
        x, y = y, x - q * y
    return (g, x, y)

