def interleave_chunks(a, b, k):
    def helper(x, y, from_x):
        if not x and not y:
            return []
        if from_x:
            if x:
                return x[:k] + helper(x[k:], y, False)
            return helper(x, y, False)
        else:
            if y:
                return y[:k] + helper(x, y[k:], True)
            return helper(x, y, True)

    return helper(a, b, True)

