def capitalize_after_colon(s):
    lowered = s.lower()
    chars = list(lowered)

    def capitalize_from(idx):
        while idx < len(chars) and not chars[idx].isalpha():
            idx += 1
        if idx < len(chars):
            chars[idx] = chars[idx].upper()

    marker_positions = []
    start = 0
    while True:
        pos = lowered.find(': ', start)
        if pos == -1:
            break
        marker_positions.append(pos + 2)
        start = pos + 1

    capitalize_from(0)
    for pos in marker_positions:
        capitalize_from(pos)

    return ''.join(chars)

