def convert_base_to_base(s, from_base, to_base):
    alphabet = '0123456789abcdefghijklmnopqrstuvwxyz'
    value_of = {ch: i for i, ch in enumerate(alphabet)}
    value = 0
    for ch in s.lower():
        value = value * from_base + value_of[ch]
    if value == 0:
        return '0'
    out = ''
    while value > 0:
        value, rem = divmod(value, to_base)
        out = alphabet[rem] + out
    return out

